"""Migrated Meridian CRM opportunity_pipeline workflow."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _positive_amount(record: dict) -> bool:
    """Evaluate the VRL guard: NVL(AMT, 0) > 0."""
    value: Any = record.get("AMT", "")
    if value is None or value == "":
        value = 0

    try:
        number = Decimal(str(value).strip())
    except (InvalidOperation, ValueError):
        return False

    return number.is_finite() and number > 0


def _valid_close_date(record: dict) -> bool:
    """Evaluate the VRL guard: CLOSE_DT <> '00000000'."""
    value = record.get("CLOSE_DT", "")
    if value is None:
        value = ""
    return str(value) != "00000000"


def _has_lost_reason(record: dict) -> bool:
    """Evaluate the VRL guard: LOST_RSN <> ''."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity_pipeline transition."""
    new_record = record.copy()
    target_state: str | None = None
    actions: tuple[tuple[str, str, str] | tuple[str, str], ...] = ()

    if state == "P" and event == "qualify" and _positive_amount(record):
        target_state = "Q"
        actions = (
            ("set", "STAGE_PCT", "25"),
            ("audit", "OPP_QUAL"),
        )
    elif state == "Q" and event == "advance":
        target_state = "N"
        actions = (("set", "STAGE_PCT", "60"),)
    elif state == "N" and event == "close_won" and _valid_close_date(record):
        target_state = "W"
        actions = (
            ("set", "STAGE_PCT", "100"),
            ("audit", "OPP_WON"),
            ("notify", "won_deal"),
        )
    elif state == "P" and event == "close_lost" and _has_lost_reason(record):
        target_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )
    elif state == "Q" and event == "close_lost" and _has_lost_reason(record):
        target_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )
    elif state == "N" and event == "close_lost" and _has_lost_reason(record):
        target_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST"),
        )

    if target_state is None:
        return {
            "state": state,
            "record": new_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    audits: list[str] = []
    notifies: list[str] = []

    for action in actions:
        if action[0] == "set":
            new_record[action[1]] = action[2]
        elif action[0] == "audit":
            audits.append(action[1])
        elif action[0] == "notify":
            notifies.append(action[1])

    return {
        "state": target_state,
        "record": new_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
